//! opengl32 (and gdi32's pixel format calls): kura's GL (crates/kura/src/gl, drawn with the
//! page's WebGPU), the same one Wine's winebrowser.drv uses. Every GL export and every
//! wglGetProcAddress result is a trap whose handler reads the stdcall arguments by the
//! function's signature (gl_sigs.rs, generated by host/gen-sake-gl.py) and calls kura's
//! function. Contexts are kura's; a context draws to the window of the DC it was made
//! current with.

#![allow(non_snake_case)]

use crate::HashMap;
use std::sync::{Mutex, OnceLock};

use crate::api::{host_fn, implement, Ctx};
use crate::gl_sigs::{self, Ret};
use crate::mem::{self, r32, w16, w32};

/// name -> trap, for wglGetProcAddress
static PROCS: Mutex<Option<HashMap<String, u32>>> = Mutex::new(None);
/// strings kura returns (glGetString), copied once into guest memory
static STRS: Mutex<Option<HashMap<usize, u32>>> = Mutex::new(None);

fn sig_of(name: &str) -> Option<u16> {
    gl_sigs::FUNCS.binary_search_by(|(n, _)| n.cmp(&name)).ok().map(|i| gl_sigs::FUNCS[i].1)
}

/// kura's function (by its name or the ARB/EXT one's core name) and signature
fn host_proc(name: &str) -> Option<(usize, u16)> {
    let base = name.strip_suffix("ARB").or_else(|| name.strip_suffix("EXT")).unwrap_or(name);
    let proc = |n: &str| {
        let c = std::ffi::CString::new(n).ok()?;
        let f = unsafe { kura::gl::vngl_proc(c.as_ptr()) } as usize;
        (f != 0).then_some(f)
    };
    let f = proc(name).or_else(|| proc(base))?;
    Some((f, sig_of(name).or_else(|| sig_of(base))?))
}

fn stack_bytes(sig: u16) -> u32 {
    gl_sigs::SIGS[sig as usize].0.chars().map(|k| if k == 'd' { 8 } else { 4 }).sum()
}

/// A GL trap's tag (crate::api::set_tag; the data is kura's function): SIG_SET | the signature,
/// with RET_STR when the result is a host string (glGetString, glGetStringi) to copy out.
const SIG_SET: u32 = 1 << 31;
const RET_STR: u32 = 1 << 16;

fn gl_tag(name: &str, sig: u16) -> u32 {
    SIG_SET | sig as u32 | if matches!(name, "glGetString" | "glGetStringi") { RET_STR } else { 0 }
}

fn dispatch(c: &mut Ctx) -> u32 {
    // (kept with the trap: no lock, no lookup per call)
    let (mut tag, mut f) = crate::api::tag_of(c.trap);
    if tag == 0 {
        // an opengl32 export, the first call: by its name
        let Some((t, e)) = crate::api::name_of(c.trap).and_then(|n| {
            let name = n.split('!').nth(1)?;
            let (f, sig) = host_proc(name)?;
            Some((gl_tag(name, sig), f))
        }) else {
            missing(c.trap);
            return 0;
        };
        crate::api::set_tag(c.trap, t, e);
        (tag, f) = (t, e);
    }
    let sig = tag as u16;
    // (12 words at most: gl_sigs::call reads w[..12])
    let mut w = [0u32; 16];
    let mut n = 0;
    if mem::x64() {
        // x64: argument i in RCX/RDX/R8/R9 or XMM0-3 by position, then the stack; pointers
        // and GLsizeiptr pass their low half
        for (i, k) in gl_sigs::SIGS[sig as usize].0.chars().enumerate() {
            match k {
                'd' => {
                    let v = c.xmm(i as u32);
                    w[n] = v as u32;
                    w[n + 1] = (v >> 32) as u32;
                    n += 2;
                }
                'f' => {
                    w[n] = c.xmm(i as u32) as u32;
                    n += 1;
                }
                _ => {
                    w[n] = c.a64(i as u32) as u32;
                    n += 1;
                }
            }
        }
    } else {
        n = (stack_bytes(sig) / 4) as usize;
        for (i, x) in w[..n].iter_mut().enumerate() {
            *x = r32(c.esp + 4 + 4 * i as u32);
        }
    }
    match unsafe { gl_sigs::call(sig, f as *const (), &w[..n]) } {
        Ret::V => 0,
        Ret::I(v) => {
            if v != 0 && tag & RET_STR != 0 {
                guest_str(v as usize)
            } else {
                v
            }
        }
        Ret::F(x) => {
            c.st0 = Some(x);
            0
        }
    }
}

/// Calls kura's GL function `name` with the stdcall argument words `w` (doubles as two words,
/// low first; floats as their bits): its integer result, or 0 (none, or no such function).
pub fn call_gl(name: &str, w: &[u32]) -> u32 {
    call_proc(host_proc(name), w)
}

/// kura's GL function `name` and its signature, for callers that keep it (glu's per-vertex
/// calls look a function up once, not per call)
pub fn gl_proc(name: &str) -> Option<(usize, u16)> {
    host_proc(name)
}

/// Calls a function `gl_proc` found with the argument words `w`: missing words are 0 and extra
/// ones are left out, so a caller's slip is a wrong argument, not an index past the end
/// (gl_sigs::call reads as many words as the signature has).
pub fn call_proc(p: Option<(usize, u16)>, w: &[u32]) -> u32 {
    let Some((f, sig)) = p else { return 0 };
    let words = fit(sig, w);
    match unsafe { gl_sigs::call(sig, f as *const (), &words) } {
        Ret::I(v) => v,
        _ => 0,
    }
}

/// `w` as exactly the words signature `sig` takes (a double: two): cut, or padded with 0
fn fit(sig: u16, w: &[u32]) -> std::borrow::Cow<'_, [u32]> {
    let n = gl_sigs::SIGS.get(sig as usize).map_or(0, |_| (stack_bytes(sig) / 4) as usize);
    if w.len() == n {
        return std::borrow::Cow::Borrowed(w);
    }
    let mut v = w[..w.len().min(n)].to_vec();
    v.resize(n, 0);
    std::borrow::Cow::Owned(v)
}

/// a NUL-terminated host string, copied into guest memory (once)
fn guest_str(p: usize) -> u32 {
    *STRS.lock().unwrap().get_or_insert_with(HashMap::default).entry(p).or_insert_with(|| {
        let s = unsafe { std::ffi::CStr::from_ptr(p as *const std::ffi::c_char) }.to_bytes();
        let g = mem::heap_alloc(s.len() as u32 + 1, true);
        mem::write(g, s);
        g
    })
}

/// A trap for GL function `name` (wglGetProcAddress), 0 if kura has none.
fn proc_trap(name: &str) -> u32 {
    if let Some(&t) = PROCS.lock().unwrap().get_or_insert_with(HashMap::default).get(name) {
        return t;
    }
    let t = match name {
        "wglCreateContextAttribsARB" => host_fn(name, wglCreateContextAttribsARB, 12),
        "wglSwapIntervalEXT" => host_fn(name, one, 4),
        "wglGetSwapIntervalEXT" => host_fn(name, one, 0),
        "wglGetExtensionsStringARB" => host_fn(name, wglGetExtensionsStringARB, 4),
        "wglGetExtensionsStringEXT" => host_fn(name, wglGetExtensionsStringARB, 0),
        "wglChoosePixelFormatARB" => host_fn(name, wglChoosePixelFormatARB, 24),
        "wglGetPixelFormatAttribivARB" => host_fn(name, wglGetPixelFormatAttribivARB, 24),
        "wglMakeContextCurrentARB" => host_fn(name, wglMakeContextCurrentARB, 12),
        "wglGetCurrentReadDCARB" => host_fn(name, wglGetCurrentDC, 0),
        _ => match host_proc(name) {
            Some(e) => {
                let t = host_fn(name, dispatch, stack_bytes(e.1));
                crate::api::set_tag(t, gl_tag(name, e.1), e.0);
                t
            }
            // one kura does not have: does nothing (as on Wine's winebrowser.drv)
            None => match gl_sigs::STUBS.binary_search_by(|(n, _)| n.cmp(&name)) {
                Ok(i) => host_fn(name, nothing, gl_sigs::STUBS[i].1 as u32),
                Err(_) => return 0,
            },
        },
    };
    PROCS.lock().unwrap().get_or_insert_with(HashMap::default).insert(name.into(), t);
    t
}

// ---- WGL ----

// this thread's (context, DC)
thread_local! {
    static CUR: std::cell::Cell<(u32, u32)> = const { std::cell::Cell::new((0, 0)) };
}

/// This thread's (context, DC) (save states keep it: snap.rs).
pub(crate) fn current_pair() -> (u32, u32) {
    CUR.with(|c| c.get())
}
pub(crate) fn set_current_pair(v: (u32, u32)) {
    CUR.with(|c| c.set(v))
}

/// glMapBuffer's memory is the program's own (kura copies the buffer there and back).
fn guest_alloc() {
    unsafe extern "C" fn alloc(size: u32) -> *mut u8 {
        mem::alloc(size).unwrap_or(0) as usize as *mut u8
    }
    unsafe extern "C" fn free(p: *mut u8) {
        mem::release(p as usize as u32);
    }
    static ONCE: std::sync::Once = std::sync::Once::new();
    ONCE.call_once(|| kura::gl::vngl_set_alloc(alloc, free));
}

fn wglCreateContext(_: &mut Ctx) -> u32 {
    guest_alloc();
    kura::gl::vngl_context_create(0)
}
fn wglCreateContextAttribsARB(c: &mut Ctx) -> u32 {
    guest_alloc();
    kura::gl::vngl_context_create(c.a(1))
}
fn wglDeleteContext(c: &mut Ctx) -> u32 {
    // (the current one: not current any more, as on Windows; CUR kept naming the destroyed
    // context for SwapBuffers, later calls and save states)
    if c.a(0) != 0 && CUR.with(|x| x.get().0) == c.a(0) {
        make_current(0, 0);
    }
    kura::gl::vngl_context_destroy(c.a(0));
    1
}

fn make_current(dc: u32, ctx: u32) -> u32 {
    if ctx == 0 {
        CUR.with(|x| x.set((0, 0)));
        return kura::gl::vngl_make_current(0, 0, 0, 0) as u32;
    }
    let hwnd = crate::gdi::dc_window(dc);
    let (w, h) = crate::user::client_rect_screen(hwnd).map_or((1, 1), |r| ((r.r - r.l).max(1) as u32, (r.b - r.t).max(1) as u32));
    CUR.with(|x| x.set((ctx, dc)));
    kura::gl::vngl_make_current(ctx, hwnd, w, h) as u32
}
fn wglMakeCurrent(c: &mut Ctx) -> u32 {
    make_current(c.a(0), c.a(1))
}
fn wglMakeContextCurrentARB(c: &mut Ctx) -> u32 {
    make_current(c.a(0), c.a(2))
}
fn wglGetCurrentContext(_: &mut Ctx) -> u32 {
    CUR.with(|x| x.get().0)
}
fn wglGetCurrentDC(_: &mut Ctx) -> u32 {
    CUR.with(|x| x.get().1)
}
fn wglGetProcAddress(c: &mut Ctx) -> u32 {
    let name = String::from_utf8_lossy(&mem::cstr(c.a(0))).into_owned();
    let t = proc_trap(&name);
    if crate::env_on!("SAKE_TRACE_GL") && host_proc(&name).is_none() {
        eprintln!("sake: wglGetProcAddress({name}): {}", if t == 0 { "none" } else { "does nothing" });
    }
    t
}
fn one(_: &mut Ctx) -> u32 {
    1
}
fn nothing(c: &mut Ctx) -> u32 {
    missing(c.trap);
    0
}

/// (MASU_API_COUNTS: a GL call kura has no function for)
fn missing(trap: u32) {
    if kura::usage::on() {
        let n = crate::api::name_of(trap).unwrap_or_default();
        kura::usage::named("glmissing", n.rsplit('!').next().unwrap_or(""));
    }
}
fn wglGetExtensionsStringARB(_: &mut Ctx) -> u32 {
    static S: OnceLock<u32> = OnceLock::new();
    *S.get_or_init(|| {
        let s = b"WGL_ARB_extensions_string WGL_EXT_extensions_string WGL_ARB_create_context WGL_EXT_swap_control WGL_ARB_pixel_format\0";
        let g = mem::heap_alloc(s.len() as u32, true);
        mem::write(g, s);
        g
    })
}
/// wglChoosePixelFormatARB(dc, iattribs, fattribs, max, formats, count): the one format
fn wglChoosePixelFormatARB(c: &mut Ctx) -> u32 {
    if c.a(3) > 0 {
        mem::put32(c.a(4), 1);
    }
    mem::put32(c.a(5), 1);
    1
}
/// wglGetPixelFormatAttribivARB(dc, format, layer, n, attribs, values)
fn wglGetPixelFormatAttribivARB(c: &mut Ctx) -> u32 {
    let (n, attrs, vals) = (c.a(3), c.a(4), c.a(5));
    for i in 0..n {
        let v = match r32(attrs + 4 * i) {
            0x2000 => 1,                  // NUMBER_PIXEL_FORMATS
            0x2001 | 0x2010 | 0x2011 => 1, // DRAW_TO_WINDOW, SUPPORT_OPENGL, DOUBLE_BUFFER
            0x2003 => 0x2027,             // ACCELERATION: FULL
            0x2013 => 0x202b,             // PIXEL_TYPE: RGBA
            0x2014 => 32,                 // COLOR_BITS
            0x2015 | 0x2017 | 0x2019 | 0x201b => 8,
            0x2022 => 24,                 // DEPTH_BITS
            0x2023 => 8,                  // STENCIL_BITS
            _ => 0,
        };
        w32(vals + 4 * i, v);
    }
    1
}

/// SwapBuffers / wglSwapBuffers(dc)
fn SwapBuffers(c: &mut Ctx) -> u32 {
    let hwnd = crate::gdi::dc_window(c.a(0));
    let Some(r) = crate::user::client_rect_screen(hwnd) else { return 1 };
    let rect = [r.l, r.t, r.r, r.b];
    unsafe { kura::gl::vngl_swap(hwnd, rect.as_ptr()) };
    1
}

/// wglSwapLayerBuffers(dc, planes): WGL_SWAP_MAIN_PLANE (1) is SwapBuffers; overlay and underlay
/// planes do not exist here and are left alone; TRUE (EntisGLS presents with it: unimplemented,
/// its screen stayed black; winref gl)
fn wglSwapLayerBuffers(c: &mut Ctx) -> u32 {
    if c.a(1) & 1 != 0 {
        return SwapBuffers(c);
    }
    1
}

// ---- pixel formats (gdi32): one, 32-bit RGBA, 24-bit depth, 8-bit stencil, double buffered ----

fn ChoosePixelFormat(_: &mut Ctx) -> u32 {
    1
}
fn SetPixelFormat(_: &mut Ctx) -> u32 {
    1
}
fn GetPixelFormat(_: &mut Ctx) -> u32 {
    1
}
/// DescribePixelFormat(dc, format, size, PIXELFORMATDESCRIPTOR*) -> the number of formats
fn DescribePixelFormat(c: &mut Ctx) -> u32 {
    let (fmt, size, p) = (c.a(1), c.a(2), c.a(3));
    if p != 0 && fmt == 1 && size >= 40 {
        mem::fill(p, 40, 0);
        w16(p, 40);
        w16(p + 2, 1);
        w32(p + 4, 0x4 | 0x20 | 0x1); // DRAW_TO_WINDOW, SUPPORT_OPENGL, DOUBLEBUFFER
        mem::w8(p + 8, 0); // RGBA
        mem::w8(p + 9, 32);
        for (o, v) in [(10, 8), (11, 16), (12, 8), (13, 8), (14, 8), (15, 0), (16, 8), (17, 24), (23, 24), (24, 8)] {
            mem::w8(p + o, v);
        }
    }
    1
}

pub fn init() {
    for (n, _) in gl_sigs::FUNCS {
        implement("opengl32", n, dispatch);
    }
    for (n, f) in [
        ("wglCreateContext", wglCreateContext as crate::api::Handler),
        ("wglDeleteContext", wglDeleteContext),
        ("wglMakeCurrent", wglMakeCurrent),
        ("wglGetCurrentContext", wglGetCurrentContext),
        ("wglGetCurrentDC", wglGetCurrentDC),
        ("wglGetProcAddress", wglGetProcAddress),
        ("wglShareLists", one),
        ("wglSwapBuffers", SwapBuffers),
        ("wglSwapLayerBuffers", wglSwapLayerBuffers),
        ("wglChoosePixelFormat", ChoosePixelFormat),
        ("wglSetPixelFormat", SetPixelFormat),
        ("wglGetPixelFormat", GetPixelFormat),
        ("wglDescribePixelFormat", DescribePixelFormat),
    ] {
        implement("opengl32", n, f);
    }
    for (n, f) in [
        ("ChoosePixelFormat", ChoosePixelFormat as crate::api::Handler),
        ("SetPixelFormat", SetPixelFormat),
        ("GetPixelFormat", GetPixelFormat),
        ("DescribePixelFormat", DescribePixelFormat),
        ("SwapBuffers", SwapBuffers),
    ] {
        implement("gdi32", n, f);
    }
}

/// A GL trap carries kura's function and its signature (dispatch reads them without a lock:
/// review C-2); glGetString's says its result is a string to copy out.
#[cfg(all(test, target_os = "linux", target_arch = "x86_64"))]
mod tag_tests {
    use super::*;

    #[test]
    fn traps_carry_function_and_signature() {
        let _g = crate::test_guest::enter();
        for name in ["glClear", "glGetString", "glGetStringi", "glTexImage2D", "glClearColor", "glBindBufferARB"] {
            let Some((f, sig)) = host_proc(name) else { continue };
            let t = proc_trap(name);
            assert_ne!(t, 0, "{name}");
            let (tag, data) = crate::api::tag_of(t);
            assert_eq!(tag & !RET_STR, SIG_SET | sig as u32, "{name}");
            assert_eq!(tag & RET_STR != 0, name.starts_with("glGetString"), "{name}");
            assert_eq!(data, f, "{name}");
            assert_eq!(crate::api::args_of(t), (false, stack_bytes(sig)));
        }
        assert!(host_proc("glClear").is_some(), "kura has glClear");
    }
}

#[cfg(test)]
mod fit_tests {
    use super::{fit, gl_sigs, stack_bytes};
    use proptest::prelude::*;

    /// gl_sigs::call's arms index words 0..n-1 of signature n: the highest word an arm reads,
    /// from its source text, must be below what `fit` hands it
    #[test]
    fn every_arm_reads_inside_the_fitted_words() {
        let src = include_str!("gl_sigs.rs");
        let body = &src[src.find("pub unsafe fn call(").unwrap()..src.find("/// GL functions kura does not have").unwrap()];
        let mut seen = 0;
        for line in body.lines() {
            let Some((sig, rest)) = line.trim().split_once(" => ") else { continue };
            let Ok(sig) = sig.parse::<u16>() else { continue };
            let top = rest.match_indices("w[").filter_map(|(i, _)| rest[i + 2..].split(']').next()?.parse::<usize>().ok()).max();
            let n = stack_bytes(sig) as usize / 4;
            if let Some(top) = top {
                assert!(top < n, "signature {sig} ({}) reads w[{top}] of {n}", gl_sigs::SIGS[sig as usize].0);
            }
            seen += 1;
        }
        assert_eq!(seen, gl_sigs::SIGS.len(), "an arm per signature");
    }

    proptest! {
        #[test]
        fn fitted_words_are_the_signatures(sig in 0..gl_sigs::SIGS.len() as u16, w in proptest::collection::vec(any::<u32>(), 0..16)) {
            let n = stack_bytes(sig) as usize / 4;
            let f = fit(sig, &w);
            prop_assert_eq!(f.len(), n);
            let k = n.min(w.len());
            prop_assert_eq!(&f[..k], &w[..k]);
            prop_assert!(f[k..].iter().all(|&x| x == 0));
        }
    }
}
